#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: cadastra uma conexao SSO (uma empresa cliente) em
# backend/sso-connections.local.json, que o backend carrega no boot.
# ──────────────────────────────────────────────────────────────────────────

BACKEND_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="$BACKEND_DIR/.env"
CONN_FILE="$BACKEND_DIR/sso-connections.local.json"
TOTAL_STAGES=4

banner "MFA-login · conexao SSO corporativa (OIDC / SAML)"

# ── 1. URL base ───────────────────────────────────────────────────────────
stage "URL do backend"
say "A URL do backend define o Redirect URI / ACS URL que a empresa cliente"
say "precisa cadastrar no IdP dela."
ask BACKEND_URL "URL do backend (Enter = http://localhost:3000):"
BACKEND_URL="${BACKEND_URL:-http://localhost:3000}"
BACKEND_URL="${BACKEND_URL%/}"
write_env BACKEND_URL "$BACKEND_URL"
pause

# ── 2. Empresa ────────────────────────────────────────────────────────────
stage "Empresa cliente"
say "Cada conexao e ligada a um dominio de email. Quem logar com @dominio vai pro IdP dela."
printf '  %sNome da empresa (ex: Acme):%s ' "$BOLD" "$RESET"; read -r CONN_NAME || true
printf '  %sDominio de email (ex: acme.com):%s ' "$BOLD" "$RESET"; read -r CONN_DOMAIN || true
CONN_DOMAIN="$(printf '%s' "$CONN_DOMAIN" | tr '[:upper:]' '[:lower:]' | sed 's/^@//')"
[[ -z "$CONN_NAME" || -z "$CONN_DOMAIN" ]] && { warn "nome e dominio sao obrigatorios"; exit 1; }
printf '\n'
say "Protocolo:"
note "  1) OIDC  - Azure AD / Entra ID, Okta, Google Workspace, Keycloak, Auth0 (recomendado)"
note "  2) SAML  - IdPs antigos ou que so oferecem SAML"
printf '  %sEscolha [1/2] (Enter = 1):%s ' "$BOLD" "$RESET"; read -r CONN_PROTO || true
CONN_TYPE="oidc"; [[ "$CONN_PROTO" == "2" ]] && CONN_TYPE="saml"
pause

# ── 3. Dados do IdP ───────────────────────────────────────────────────────
if [[ "$CONN_TYPE" == "oidc" ]]; then
  stage "OIDC · dados do IdP da empresa"
  say "A empresa cliente registra um app no IdP dela e te passa issuer, client ID e secret."
  say "Redirect URI que ELA precisa cadastrar (manda pro responsavel de TI):"
  say "    ${BOLD}${BACKEND_URL}/sso/oidc/callback${RESET}"
  printf '\n'
  say "Issuer por provedor:"
  note "  Azure AD / Entra:  https://login.microsoftonline.com/<TENANT_ID>/v2.0"
  note "  Okta:              https://<org>.okta.com   (ou .../oauth2/default)"
  note "  Google Workspace:  https://accounts.google.com"
  note "  Keycloak:          https://<host>/realms/<realm>"
  note "  Auth0:             https://<tenant>.auth0.com/"
  printf '  %sIssuer:%s ' "$BOLD" "$RESET"; read -r OIDC_ISSUER || true
  printf '  %sClient ID:%s ' "$BOLD" "$RESET"; read -r OIDC_CLIENT_ID || true
  printf '  %sClient secret (oculto):%s ' "$BOLD" "$RESET"; read -rs OIDC_SECRET || true; printf '\n'
  [[ -z "$OIDC_ISSUER" || -z "$OIDC_CLIENT_ID" || -z "$OIDC_SECRET" ]] && { warn "issuer, client ID e secret sao obrigatorios"; exit 1; }
  if command -v curl >/dev/null 2>&1; then
    if curl -fsS "${OIDC_ISSUER%/}/.well-known/openid-configuration" >/dev/null 2>&1; then
      printf '  %s✓%s discovery do issuer respondeu\n' "$GREEN" "$RESET"
    else
      warn "nao consegui ler ${OIDC_ISSUER%/}/.well-known/openid-configuration (confira o issuer)"
    fi
  fi
else
  stage "SAML · dados do IdP da empresa"
  say "A empresa cadastra nosso SP no IdP dela com estes valores:"
  say "    ACS URL:   ${BOLD}${BACKEND_URL}/sso/saml/callback/<id>${RESET}"
  say "    Metadata:  ${BOLD}${BACKEND_URL}/sso/saml/metadata/<id>${RESET}"
  note "  (<id> e gerado agora e mostrado no final)"
  printf '\n'
  printf '  %sSSO URL / entryPoint do IdP:%s ' "$BOLD" "$RESET"; read -r SAML_ENTRY || true
  say "Certificado X.509 do IdP: caminho de um arquivo .pem/.crt/.cer"
  printf '  %sCaminho do certificado:%s ' "$BOLD" "$RESET"; read -r SAML_CERT_PATH || true
  SAML_CERT_PATH="$(printf '%s' "$SAML_CERT_PATH" | tr -d "\"'")"
  if command -v cygpath >/dev/null 2>&1; then SAML_CERT_PATH="$(cygpath -u "$SAML_CERT_PATH")"; fi
  [[ -z "$SAML_ENTRY" || ! -f "$SAML_CERT_PATH" ]] && { warn "entryPoint e certificado sao obrigatorios"; exit 1; }
  SAML_CERT="$(grep -v 'CERTIFICATE' "$SAML_CERT_PATH" | tr -d '\r\n ')"
fi
pause

# ── 4. Gravar ─────────────────────────────────────────────────────────────
stage "Gravar conexao"
CONN_ID="$(cat /proc/sys/kernel/random/uuid 2>/dev/null || node -e 'console.log(require("crypto").randomUUID())')"
[[ -f "$CONN_FILE" ]] || printf '[]\n' > "$CONN_FILE"
if ! command -v node >/dev/null 2>&1; then warn "node nao encontrado; nao consigo gravar $CONN_FILE"; exit 1; fi
CONN_FILE="$CONN_FILE" CONN_ID="$CONN_ID" CONN_NAME="$CONN_NAME" CONN_DOMAIN="$CONN_DOMAIN" CONN_TYPE="$CONN_TYPE" \
OIDC_ISSUER="${OIDC_ISSUER:-}" OIDC_CLIENT_ID="${OIDC_CLIENT_ID:-}" OIDC_SECRET="${OIDC_SECRET:-}" \
SAML_ENTRY="${SAML_ENTRY:-}" SAML_CERT="${SAML_CERT:-}" node -e '
  const fs = require("fs"); const e = process.env;
  let list = []; try { list = JSON.parse(fs.readFileSync(e.CONN_FILE, "utf-8")); } catch {}
  list = list.filter((c) => c.domain !== e.CONN_DOMAIN);
  const conn = { id: e.CONN_ID, name: e.CONN_NAME, domain: e.CONN_DOMAIN, type: e.CONN_TYPE };
  if (e.CONN_TYPE === "oidc") conn.oidc = { issuer: e.OIDC_ISSUER, clientId: e.OIDC_CLIENT_ID, clientSecret: e.OIDC_SECRET };
  else conn.saml = { entryPoint: e.SAML_ENTRY, idpCert: e.SAML_CERT };
  list.push(conn);
  fs.writeFileSync(e.CONN_FILE, JSON.stringify(list, null, 2) + "\n");
'
printf '  %s✓ gravado%s %s (%s, %s) → %s\n' "$GREEN" "$RESET" "$CONN_NAME" "$CONN_DOMAIN" "$CONN_TYPE" "$CONN_FILE"
WRITTEN_ENV+=("sso:$CONN_DOMAIN")
printf '\n'
if [[ "$CONN_TYPE" == "saml" ]]; then
  say "Passe pra empresa:"
  say "    ACS URL:  ${BOLD}${BACKEND_URL}/sso/saml/callback/${CONN_ID}${RESET}"
  say "    Metadata: ${BOLD}${BACKEND_URL}/sso/saml/metadata/${CONN_ID}${RESET}"
else
  say "Passe pra empresa o Redirect URI: ${BOLD}${BACKEND_URL}/sso/oidc/callback${RESET}"
fi
printf '\n'
say "Reinicie o backend pra carregar. Teste em FRONTEND_URL/sso com um email @${CONN_DOMAIN}."
note "Rode de novo pra cadastrar outra empresa. Mesmo dominio = substitui."
pause

finish
